#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Grids;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Grids;
using PVZEngine.Models;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.teleporter)]
    public class Teleporter : EntityBehaviourDefinition
    {
        public Teleporter(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            entity.SetAnimationBool("Signal", entity.IsEvoked());
        }
        public static void Teleport(Entity teleporter, LawnGrid lawnGrid)
        {
            var level = teleporter.Level;
            var thisColumn = Mathf.Clamp(teleporter.GetColumn(), 0, level.GetMaxColumnCount() - 1);
            var thisLane = Mathf.Clamp(teleporter.GetLane(), 0, level.GetMaxLaneCount() - 1);

            var targetEntity = lawnGrid.GetMainEntity();
            if (targetEntity != null && !targetEntity.NoTeleporter())
            {
                TeleportToTile(targetEntity, thisColumn, thisLane);
            }

            TeleportToTile(teleporter, lawnGrid.Column, lawnGrid.Lane);
            teleporter.PlaySound(VanillaSoundID.teleportUp);
        }
        private static void TeleportToTile(Entity entity, int column, int lane)
        {
            var level = entity.Level;
            var position = level.GetEntityGridPosition(column, lane);
            var buff = entity.AddBuff<TeleporterTeleportUpBuff>();
            var tileOffset2D = entity.GetGridPivotOffset();
            var tileOffset = new Vector3(tileOffset2D.x, 0, tileOffset2D.y);
            TeleporterTeleportUpBuff.SetTargetPosition(buff, position + tileOffset);

            bool changingLane = entity.IsChangingLane();
            bool changingTile = entity.IsChangingTile();
            if (changingLane || changingTile)
            {
                if (changingTile)
                {
                    entity.StopChangingGrid();
                }
                if (changingLane)
                {
                    entity.StopChangingLane();
                }
                entity.AdjustToTile();
            }
        }
    }
}
